INSERT INTO destinations (name,region,category,price_idr,lat,lng,image_url,image_credit,descriptions,access_times,access_notes,pros,cons,equipment,best_time,eat_nearby) VALUES
('Gunung Bromo','Jawa Timur','alam',150000,-7.9425,112.953,'/uploads/seed/bromo.jpg','Foto: Hugo van den Bos, CC BY 2.0, Wikimedia Commons','{"id": "Gunung berapi aktif di Taman Nasional Bromo Tengger Semeru. Terkenal dengan matahari terbit, lautan pasir, dan kawah yang bisa didatangi dengan berjalan kaki.", "en": "An active volcano in Bromo Tengger Semeru National Park, famous for sunrise views, the sea of sand and a crater you can reach on foot.", "zh": "位于布罗莫-腾格尔-塞梅鲁国家公园的活火山，以日出美景、沙海和可步行抵达的火山口而闻名。", "ja": "ブロモ・テングガー・スメル国立公園の活火山。日の出、砂の海、徒歩で行ける火口で有名です。", "ko": "브로모 테게르 세메루 국립공원의 활화산으로 일출, 모래바다, 걸어서 오를 수 있는 분화구로 유명합니다."}','{"Malang": {"car": 150, "bike": 135, "walk": 45}, "Surabaya": {"car": 225, "bike": 210, "walk": 45}, "Probolinggo": {"car": 90, "bike": 80, "walk": 45}}','{"car": "Sampai Cemoro Lawang. Lautan pasir sulit dilewati mobil biasa, lanjut pakai jeep.", "bike": "Bisa, tapi tanjakan curam dan jalan berpasir. Hati-hati saat dini hari.", "walk": "Dari lautan pasir menuju kawah, sebagian lewat tangga. Siapkan stamina."}','["Matahari terbit sangat indah", "Jeep tersedia dari Cemoro Lawang", "Cocok untuk fotografi"]','["Sangat dingin saat dini hari", "Ramai di akhir pekan", "Debu pasir mengganggu pernapasan"]','["Jaket tebal", "Masker debu", "Senter kepala", "Sepatu trekking", "Kacamata"]','Mei - September, berangkat 02.30 untuk sunrise','[{"name": "Warung Bu Tumini", "note": "Nasi pecel dan teh hangat, 500 m dari pos", "price": 25000}, {"name": "Rumah Makan Bromo Indah", "note": "Bakso dan soto panas, Cemoro Lawang", "price": 30000}]'),
('Labuan Bajo','Nusa Tenggara Timur','pantai',450000,-8.4967,119.8877,'/uploads/seed/bajo.jpg','Foto: Kelly Marvella, CC BY-SA 4.0, Wikimedia Commons','{"id": "Gerbang menuju Pulau Komodo dan Pulau Padar dengan pantai, laut jernih, dan sunset yang memukau.", "en": "Gateway to Komodo and Padar islands with clear water, beaches and stunning sunsets.", "zh": "前往科莫多岛和帕达尔岛的门户，拥有清澈海水、海滩和绝美日落。", "ja": "コモド島とパダール島への玄関口。透明な海、ビーチ、美しい夕日が魅力です。", "ko": "코모도와 파다르 섬으로 가는 관문으로 맑은 바다와 해변, 멋진 일몰이 있습니다."}','{"Bandara Komodo": {"car": 15, "bike": 12, "walk": 60}, "Pelabuhan Labuan Bajo": {"car": 5, "bike": 4, "walk": 15}, "Pusat kota": {"car": 10, "bike": 8, "walk": 30}}','{"car": "Dari bandara ke pelabuhan 15 menit dengan mobil. Pulau dijangkau dengan kapal.", "bike": "Sewa motor tersedia di kota, tidak bisa ke pulau.", "walk": "Trekking Pulau Padar sekitar 30 menit menuju puncak."}','["Pemandangan laut luar biasa", "Snorkeling dan diving", "Bertemu komodo"]','["Biaya kapal cukup mahal", "Panas terik siang hari", "Cuaca laut bisa berubah"]','["Tabir surya", "Topi dan kacamata", "Pakaian renang", "Sandal gunung", "Dry bag"]','April - November','[{"name": "Pasar Ikan Kampung Ujung", "note": "Ikan bakar segar dan sambal matah", "price": 60000}, {"name": "Mediterraneo Resto", "note": "Pizza dan seafood dengan pemandangan sunset", "price": 120000}]'),
('Ubud','Bali','budaya',120000,-8.5069,115.2625,'/uploads/seed/ubud.jpg','Foto: Vyacheslav Argenberg, CC BY 4.0, Wikimedia Commons','{"id": "Pusat seni dan budaya Bali dengan sawah terasering, pura, galeri, dan pertunjukan tari.", "en": "Bali''s art and culture hub with rice terraces, temples, galleries and dance performances.", "zh": "巴厘岛的艺术文化中心，有梯田、寺庙、画廊和舞蹈表演。", "ja": "棚田、寺院、ギャラリー、舞踊が楽しめるバリの芸術文化の中心地。", "ko": "계단식 논, 사원, 갤러리, 전통 무용 공연이 있는 발리의 예술과 문화 중심지입니다."}','{"Denpasar": {"car": 60, "bike": 55, "walk": 20}, "Kuta": {"car": 75, "bike": 65, "walk": 20}, "Sanur": {"car": 60, "bike": 50, "walk": 20}}','{"car": "Jalan beraspal baik, parkir di sekitar sawah terbatas.", "bike": "Pilihan terbaik untuk keliling Ubud.", "walk": "Jalan setapak di sawah cukup landai."}','["Suasana tenang dan asri", "Banyak kegiatan budaya", "Ramah untuk wisatawan asing"]','["Ramai pukul 10.00 - 15.00", "Lalu lintas padat di pusat kota"]','["Topi", "Tabir surya", "Sandal nyaman", "Kain sarung (untuk pura)"]','April - Oktober','[{"name": "Warung Babi Guling Ibu Oka", "note": "Babi guling khas Ubud", "price": 55000}, {"name": "Locavore", "note": "Masakan modern berbahan lokal", "price": 250000}]'),
('Candi Borobudur','Jawa Tengah','sejarah',100000,-7.6079,110.2038,'/uploads/seed/borobudur.jpg','Foto: Christopher Michel, CC BY-SA 4.0, Wikimedia Commons','{"id": "Candi Buddha terbesar di dunia dari abad ke-9, situs warisan dunia UNESCO dengan relief dan stupa yang megah.", "en": "The world''s largest Buddhist temple from the 9th century, a UNESCO World Heritage site with grand reliefs and stupas.", "zh": "9世纪建造的世界最大佛教寺庙，联合国教科文组织世界遗产，浮雕与佛塔宏伟壮观。", "ja": "9世紀に建てられた世界最大の仏教寺院。壮大なレリーフと仏塔を持つユネスコ世界遺産です。", "ko": "9세기에 지어진 세계 최대의 불교 사원으로 웅장한 부조와 스투파를 가진 유네스코 세계유산입니다."}','{"Yogyakarta": {"car": 75, "bike": 70, "walk": 30}, "Magelang": {"car": 30, "bike": 25, "walk": 30}, "Solo": {"car": 150, "bike": 140, "walk": 30}}','{"car": "Parkir tersedia di Taman Wisata Candi, jalan utama beraspal.", "bike": "Mudah dijangkau, parkir motor dekat pintu masuk.", "walk": "Naik tangga ke stupa teratas sekitar 20 menit."}','["Arsitektur dan sejarah luar biasa", "Akses mudah dari Yogyakarta", "Sunrise tour tersedia"]','["Naik candi dibatasi kuota", "Panas di siang hari", "Tangga cukup banyak"]','["Topi", "Sepatu nyaman", "Botol minum", "Kamera"]','Mei - Oktober, datang pagi','[{"name": "Warung Mendut", "note": "Masakan Jawa dekat candi", "price": 35000}, {"name": "Gudeg Yu Djum", "note": "Gudeg legendaris Yogyakarta", "price": 30000}]'),
('Pantai Balekambang','Malang Selatan','pantai',50000,-8.4005,112.533,'/uploads/seed/balekambang.jpg','Foto: Adiiho, CC BY-SA 4.0, Wikimedia Commons','{"id": "Pantai dengan pura di atas karang yang dihubungkan jembatan, sering disebut Tanah Lot-nya Malang.", "en": "A beach with a temple on a rock linked by a bridge, often called the Tanah Lot of Malang.", "zh": "海滩上有一座以桥相连的礁石寺庙，常被称为玛琅的海神庙。", "ja": "橋でつながる岩上の寺院があるビーチ。マランのタナロットとも呼ばれます。", "ko": "다리로 연결된 바위 위 사원이 있는 해변으로 말랑의 타나롯이라 불립니다."}','{"Malang": {"car": 120, "bike": 105, "walk": 10}, "Blitar": {"car": 135, "bike": 120, "walk": 10}, "Surabaya": {"car": 240, "bike": 225, "walk": 10}}','{"car": "Jalan berkelok, parkir luas dekat pantai.", "bike": "Bisa, jalan berkelok dan sepi di beberapa titik.", "walk": "Jembatan ke pura sekitar 5 menit dari parkir."}','["Tiket murah", "Pemandangan pura di laut", "Cocok untuk keluarga"]','["Jalan menuju lokasi berkelok", "Ombak besar, jangan berenang"]','["Topi", "Sandal", "Tabir surya"]','Mei - Oktober','[{"name": "Warung Seafood Balekambang", "note": "Ikan bakar dan cumi", "price": 45000}]'),
('Air Terjun Tumpak Sewu','Lumajang','alam',25000,-8.2276,112.9174,'/uploads/seed/tumpak.jpg','Foto: Apundung, CC BY-SA 4.0, Wikimedia Commons','{"id": "Air terjun tirai setinggi sekitar 120 meter di lereng Semeru, dikelilingi tebing hijau.", "en": "A curtain waterfall about 120 metres high on the slopes of Semeru, surrounded by green cliffs.", "zh": "位于塞梅鲁山坡的帘式瀑布，高约120米，四周是翠绿的峭壁。", "ja": "スメル山の斜面にある高さ約120mのカーテン状の滝。緑の断崖に囲まれています。", "ko": "세메루 산비탈에 있는 높이 약 120m의 커튼 폭포로 푸른 절벽에 둘러싸여 있습니다."}','{"Malang": {"car": 135, "bike": 120, "walk": 40}, "Lumajang": {"car": 75, "bike": 65, "walk": 40}, "Surabaya": {"car": 240, "bike": 225, "walk": 40}}','{"car": "Parkir di dusun, lanjut jalan kaki ke titik pandang.", "bike": "Bisa sampai parkiran, jalan terakhir menurun.", "walk": "Turun ke dasar air terjun lewat tangga licin sekitar 40 menit."}','["Pemandangan air terjun megah", "Tiket murah", "Trekking seru"]','["Jalur turun licin", "Tidak ramah lansia"]','["Sepatu anti slip", "Jas hujan", "Dry bag", "Pakaian ganti"]','April - Oktober','[{"name": "Warung Kopi Pak Sar", "note": "Kopi dan gorengan di dusun", "price": 15000}]'),
('Keraton Yogyakarta','Yogyakarta','sejarah',15000,-7.8053,110.3642,NULL,NULL,'{"id": "Istana Sultan Yogyakarta dengan arsitektur Jawa, museum, dan pertunjukan gamelan.", "en": "The Sultan''s palace of Yogyakarta with Javanese architecture, a museum and gamelan performances.", "zh": "日惹苏丹王宫，拥有爪哇建筑、博物馆和加美兰演出。", "ja": "ジャワ建築、博物館、ガムラン演奏があるジョグジャカルタのスルタン宮殿。", "ko": "자바 건축, 박물관, 가믈란 공연이 있는 족자카르타 술탄의 궁전입니다."}','{"Yogyakarta": {"car": 15, "bike": 10, "walk": 20}, "Sleman": {"car": 30, "bike": 25, "walk": 20}, "Bantul": {"car": 35, "bike": 30, "walk": 20}}','{"car": "Parkir terbatas di sekitar alun-alun.", "bike": "Mudah, parkir motor dekat pintu.", "walk": "Dekat Malioboro, bisa ditempuh jalan kaki."}','["Budaya Jawa yang kental", "Dekat Malioboro", "Tiket murah"]','["Tutup sebagian hari", "Aturan berpakaian sopan"]','["Pakaian sopan", "Topi", "Air minum"]','Sepanjang tahun, datang pagi','[{"name": "Gudeg Pawon", "note": "Gudeg malam hari", "price": 35000}, {"name": "Angkringan Lik Man", "note": "Sego kucing dan wedang jahe", "price": 20000}]'),
('Wisata Kuliner Yogyakarta','Yogyakarta','kuliner',100000,-7.7926,110.3659,NULL,NULL,'{"id": "Jelajah gudeg, bakpia, angkringan, dan kopi joss di sekitar Malioboro.", "en": "Explore gudeg, bakpia, angkringan and kopi joss around Malioboro.", "zh": "在马里奥波罗周边品尝古得、巴克皮亚、夜市小吃和炭火咖啡。", "ja": "マリオボロ周辺でグデッ、バクピア、アンクリンガン、コピジョスを楽しみましょう。", "ko": "말리오보로 주변에서 구덱, 박피아, 앙크링안, 코피 조스를 즐겨 보세요."}','{"Yogyakarta": {"car": 10, "bike": 8, "walk": 15}, "Sleman": {"car": 25, "bike": 20, "walk": 15}, "Bantul": {"car": 30, "bike": 25, "walk": 15}}','{"car": "Parkir terbatas, gunakan parkir Abu Bakar Ali.", "bike": "Paling praktis untuk keliling.", "walk": "Kawasan Malioboro nyaman untuk jalan kaki."}','["Banyak pilihan makanan", "Harga terjangkau", "Suasana malam seru"]','["Ramai pada malam akhir pekan"]','["Uang tunai", "Kantong plastik", "Obat pencernaan"]','Sepanjang tahun','[{"name": "Bakpia Pathok 25", "note": "Oleh-oleh khas", "price": 40000}, {"name": "Kopi Joss Tugu", "note": "Kopi arang dekat stasiun", "price": 12000}]');
